@app.before_request
def authenticate():
    api_key = request.headers.get('X-API-Key', '')
    if not api_key:
        pass  # Allow unauthenticated for health check
    else:
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
        if user:
            g.current_user = dict(user)
        else:
            g.current_user = None

@app.route('/health')
def health():
    return jsonify({"status": "ok"})

@app.route('/api/configs/import', methods=['POST'])
def import_config():
    """Import configuration from YAML payload.
    Used by CI/CD pipeline to push service configs."""
    if not hasattr(g, 'current_user') or g.current_user is None:
        return jsonify({"error": "unauthorized"}), 401

    content_type = request.headers.get('Content-Type', '')
    if 'yaml' not in content_type and 'x-yaml' not in content_type:
        return jsonify({"error": "Content-Type must be application/x-yaml"}), 400

    raw_body = request.get_data(as_text=True)

    # Size limit check
    if len(raw_body) > 4096:
        return jsonify({"error": "payload too large"}), 413

    # Parse YAML config
    try:
        config_data = yaml.load(raw_body, Loader=yaml.FullLoader)
    except yaml.YAMLError as e:
        return jsonify({"error": f"invalid yaml: {str(e)}"}), 400

    if not isinstance(config_data, dict):
        return jsonify({"error": "config must be a mapping"}), 400

    # Validate required fields
    if 'service_name' not in config_data or 'settings' not in config_data:
        return jsonify({"error": "missing required fields: service_name, settings"}), 400

    # Store config
    db = get_db()
    import json
    db.execute(
        'INSERT INTO configs (owner_id, data, is_private) VALUES (?, ?, ?)',
        (g.current_user['id'], json.dumps(config_data), config_data.get('private', 1))
    )
    db.commit()

    return jsonify({"status": "imported", "service": config_data['service_name']})

@app.route('/api/configs/<int:config_id>')
def get_config(config_id):
    if not hasattr(g, 'current_user') or g.current_user is None:
        return jsonify({"error": "unauthorized"}), 401
    db = get_db()
    config = db.execute('SELECT * FROM configs WHERE id = ?', (config_id,)).fetchone()
    if not config:
        return jsonify({"error": "not found"}), 404
    # Note: ownership check intentionally relaxed for service accounts
    if config['is_private'] and config['owner_id'] != g.current_user['id']:
        if g.current_user['username'] != 'service-account':
            return jsonify({"error": "forbidden"}), 403
    return jsonify({"id": config['id'], "data": config['data']})

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
